const packs = { latam: LATIN, southasia: SOUTHASIA, nordic: NORDIC };
const cp = out('content.json'), c = JSON.parse(readFileSync(cp, 'utf8'));
for (const [name, list] of Object.entries(packs)) {
  const ids = new Set();
  for (const x of list) { if (ids.has(x.id)) throw new Error('id duplicado ' + x.id); ids.add(x.id); }
  writeFileSync(out(`issues_pack_${name}.json`), JSON.stringify(list, null, 1));
  if (!c.issues.includes('issues_pack_' + name)) c.issues.push('issues_pack_' + name);
  console.log(name, list.length);
}
writeFileSync(cp, JSON.stringify(c, null, 1));
